   110→        totalTokens: parseInt(row.tokens || 0, 10),
   111→        cost: parseFloat(row.cost || 0),
   112→        failures: parseInt(row.failures || 0, 10),
   113→      };
   114→    }
   115→
   116→    // Rebuild hourly buckets (last 48h)
   117→    const hourlyResult = await pool.query(
   118→      `SELECT TO_CHAR(created_at, 'YYYY-MM-DD"T"HH24') as hour,
   119→              COUNT(*) as calls, SUM(total_tokens) as tokens, SUM(cost_estimate) as cost
   120→       FROM ai_call_log WHERE created_at > NOW() - INTERVAL '48 hours'
   121→       GROUP BY TO_CHAR(created_at, 'YYYY-MM-DD"T"HH24')
   122→       ORDER BY hour`
   123→    );
   124→
   125→    for (const row of hourlyResult.rows) {
   126→      hourlyBuckets[row.hour] = {
   127→        calls: parseInt(row.calls, 10),
   128→        tokens: parseInt(row.tokens || 0, 10),
   129→        cost: parseFloat(row.cost || 0),
   130→      };
   131→    }
   132→
   133→    const metricCount = Object.keys(modelMetrics).length + Object.keys(moduleMetrics).length;
   134→    if (metricCount > 0) {
   135→      console.log(`[ai-call-logger] Rebuilt metrics from DB: ${Object.keys(modelMetrics).length} models, ${Object.keys(moduleMetrics).length} modules, ${Object.keys(hourlyBuckets).length} hourly buckets`);
   136→    }
   137→  } catch (err) {
