async _nimChat(model, messages, options) {
  const client = this.clients.nim;
  const msgs = [];

  if (options.system) {
    msgs.push({ role: 'system', content: options.system });
  }
  for (const m of messages) {
    if (m.role === 'system' && options.system) continue;
    msgs.push({ role: m.role, content: typeof m.content === 'string' ? m.content : String(m.content) });
  }
  if (msgs.length === 0) msgs.push({ role: 'user', content: 'Hello' });

  const params = {
    model,
    messages: msgs,
    max_tokens: options.maxTokens || options.max_tokens || 8192,
    temperature: options.temperature || 0.7,
  };

  // FIX (Feb 15, 2026 — Task #32651): Do NOT pass response_format to NIM models.
  // NIM returns null content when response_format: { type: 'json_object' } is set.
  // The prompt already asks for JSON — safeParseJSON handles extraction.

  const response = await client.chat.completions.create(params);
  const content = response.choices[0].message.content;

  // FIX: Treat null/empty content as provider failure so fallback chain continues
  if (content == null || content === '') {
    throw new Error(`NIM ${model} returned null/empty content — treating as provider failure`);
  }
  return content;
}

