  // retrying every 5 minutes and wasting time on calls that will fail.
  if (status === 429 && this._isOpenAIProvider(providerKey)) {
    const errMsg = (error.message || '').toLowerCase();
    if (errMsg.includes('daily') || errMsg.includes('limit reach') || errMsg.includes('rate_limit')) {
      if (!tokenBudget.budgetExhausted) {
        tokenBudget.budgetExhausted = true;
        tokenBudget.exhaustedAt = new Date().toISOString();
        console.log(`[ai-provider] ⚠️ OpenAI daily limit detected (429). Marking budget exhausted — routing to NIM.`);
        try {
          const { logBudgetExhausted } = require('./activity-logger');
          logBudgetExhausted(tokenBudget.tokensUsed, tokenBudget.dailyBudget);
        } catch (e) { /* activity logger not loaded yet */ }
      }
    }
  }

  const logEntry = {
    timestamp: new Date().toISOString(),
    event: 'provider_failure',
    provider: providerKey,
    modality,
    error: error.message || String(error),
    status,
  };
  this.logs.push(logEntry);
  if (this.logs.length > 100) this.logs.shift();

  console.log(`[ai-provider] ❌ ${providerKey} failed for ${modality}: [${status || 'ERR'}] ${error.message || error}`);
}

